# c5: orbits of Sp_6(2) (generated by transvections, embedded in Sp_6(8)) on PG(5,8) = H(8) points (projection from nucleus).
import numpy as np, sys, random, time, pickle
sys.path.insert(0, '/home/user/degree-diameter/research/squads/d10D7-r5/c5')
from gf8 import *
q, N, X8 = load_hex8()
# 6-vector model v = (X0,X1,X2,X4,X5,X6); omega(v,w) = sum v_i w_{i+3} + v_{i+3} w_i (char 2, GF(2) entries of J)
J = np.zeros((6, 6), dtype=np.int64)
for i in range(3): J[i, i + 3] = 1; J[i + 3, i] = 1
# all normalised points of PG(5,8)
allv = np.array([[ (c >> (3 * i)) & 7 for i in range(6)] for c in range(8 ** 6)], dtype=np.int64)
nz = allv != 0
first = np.argmax(nz, axis=1)
keep = nz.any(axis=1) & (allv[np.arange(len(allv)), first] == 1)
P6 = allv[keep]
print('PG(5,8) points', len(P6))
pw8 = 8 ** np.arange(6)
code6 = P6 @ pw8
idx6 = np.full(8 ** 6, -1, dtype=np.int64); idx6[code6] = np.arange(len(P6))
# check the hex point set equals the image of the projection
X6 = X8[:, [0, 1, 2, 4, 5, 6]]
print('hex points project to normalised 6-vectors:', bool((normalize_rows(X6) == X6).all()))
# transvections over GF(2): T = I + v v^T J (mod 2)
rng = np.random.default_rng(1)
vecs = [np.array([(c >> i) & 1 for i in range(6)]) for c in range(1, 64)]
def trans(v):
    return (np.eye(6, dtype=np.int64) + np.outer(v, (v @ J) % 2)) % 2
gens = [trans(v) for v in vecs]
# check symplectic: T^T J T = J mod 2
assert all(np.array_equal((T.T @ J @ T) % 2, J % 2) for T in gens[:10])
def perm_of(T):
    Y = gf_matvec(T, P6)
    Yn = normalize_rows(Y)
    return idx6[Yn @ pw8]
t0 = time.time()
perms = [perm_of(T) for T in gens]
print('perms built', round(time.time() - t0, 1))
M = len(P6)
parent = np.arange(M)
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]; x = parent[x]
    return x
for pm in perms:
    for x in range(M):
        a, b = find(x), find(int(pm[x]))
        if a != b: parent[a] = b
roots = np.array([find(x) for x in range(M)])
from collections import Counter
cnt = Counter(roots.tolist())
print('orbit size histogram:', sorted(Counter(cnt.values()).items()))
pickle.dump((P6, roots), open('/home/user/degree-diameter/research/squads/d10D7-r5/c5/sp62_orbits8.pkl', 'wb'))
